const PLACE_INDEX = Object.entries(COUNTY_PLACES).flatMap(([county, names]) =>
  names.split("|").map((name) => ({ county: county as County, name })));

const normalize = (text: string) => text.toLocaleLowerCase("et").trim().replace(/\s+/g, " ");
const label = (entry: (typeof PLACE_INDEX)[number]) => `${entry.name} · ${entry.county}`;

export function findPlace(input: string) {
  const query = normalize(input);
  const exact = PLACE_INDEX.filter((entry) => normalize(label(entry)) === query || normalize(entry.name) === query);
  return exact.length === 1 ? exact[0] : undefined;
}

export function suggestPlaces(input: string): string[] {
  const query = normalize(input);
  if (query.length < 2) return [];
  return PLACE_INDEX.filter((entry) => normalize(entry.name).startsWith(query)).slice(0, 8).map(label);
}
